// =========================================================
// NORMALIZAR VAGAS
// Mode: Run Once for Each Item
// =========================================================


// =========================================================
// FUNÇÕES AUXILIARES
// =========================================================

function stripHtml(html = '') {
  return String(html)
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<\/p>/gi, '\n')
    .replace(/<\/div>/gi, '\n')
    .replace(/<li[^>]*>/gi, '• ')
    .replace(/<\/li>/gi, '\n')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/gi, ' ')
    .replace(/&amp;/gi, '&')
    .replace(/&quot;/gi, '"')
    .replace(/&#39;/gi, "'")
    .replace(/&lt;/gi, '<')
    .replace(/&gt;/gi, '>')
    .replace(/\s+\n/g, '\n')
    .replace(/\n\s+/g, '\n')
    .replace(/[ \t]+/g, ' ')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}


function get(obj, keys, fallback = '') {
  for (const key of keys) {
    if (
      obj &&
      obj[key] !== undefined &&
      obj[key] !== null &&
      obj[key] !== ''
    ) {
      return obj[key];
    }
  }

  return fallback;
}


function getPath(obj, path, fallback = '') {
  try {
    const value = path
      .split('.')
      .reduce((acc, key) => acc?.[key], obj);

    if (
      value !== undefined &&
      value !== null &&
      value !== ''
    ) {
      return value;
    }

    return fallback;
  } catch {
    return fallback;
  }
}


function normalizeText(value = '') {
  return String(value)
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/\s+/g, ' ')
    .trim();
}


function firstNonEmpty(values, fallback = '') {
  for (const value of values) {
    if (
      value !== undefined &&
      value !== null &&
      String(value).trim() !== ''
    ) {
      return value;
    }
  }

  return fallback;
}


// =========================================================
// URL CANÔNICA DA VAGA
// =========================================================

function canonicalLinkedinJobUrl(raw = '', id = '') {

  if (id) {
    return `https://www.linkedin.com/jobs/view/${id}`;
  }

  try {
    const url = new URL(raw);

    const match = url.pathname.match(
      /jobs\/view\/(?:.*-)?(\d+)/
    );

    if (match) {
      return `https://www.linkedin.com/jobs/view/${match[1]}`;
    }

    url.search = '';
    url.hash = '';

    return url.toString();

  } catch {
    return raw;
  }
}


// =========================================================
// URL CANÔNICA DE PERFIL LINKEDIN
// =========================================================

function canonicalLinkedinProfileUrl(raw = '') {

  if (!raw) {
    return '';
  }

  try {
    const url = new URL(raw);

    url.search = '';
    url.hash = '';

    return url.toString()
      .replace(/\/+$/, '');

  } catch {
    return String(raw).trim();
  }
}


// =========================================================
// DETECÇÃO DE MODALIDADE
// =========================================================

function detectarModalidade(item, descricao = '') {

  // Primeiro prioriza campos explícitos
  const camposExplicitos = [
    item.workplaceTypes,
    item.workplaceType,
    item['tipos de local de trabalho'],
    item['tipo de local de trabalho'],
    item['modalidade'],
    item['workplace']
  ]
    .flat()
    .filter(Boolean)
    .join(' ');

  const explicito = normalizeText(camposExplicitos);

  if (
    explicito.includes('remote') ||
    explicito.includes('remoto')
  ) {
    return 'REMOTO';
  }

  if (
    explicito.includes('hybrid') ||
    explicito.includes('hibrido')
  ) {
    return 'HIBRIDO';
  }

  if (
    explicito.includes('on-site') ||
    explicito.includes('onsite') ||
    explicito.includes('presencial')
  ) {
    return 'PRESENCIAL';
  }


  // Se o Apify não informar explicitamente,
  // verifica apenas o início da descrição
  const desc = normalizeText(descricao).slice(0, 2500);

  if (
    /\b(100% remote|fully remote|remote position|trabalho remoto|vaga remota|100% remoto)\b/.test(desc)
  ) {
    return 'REMOTO';
  }

  if (
    /\b(hybrid|hibrido|modelo hibrido|trabalho hibrido|regime hibrido)\b/.test(desc)
  ) {
    return 'HIBRIDO';
  }

  if (
    /\b(on-site|onsite|presencial|modelo presencial|trabalho presencial)\b/.test(desc)
  ) {
    return 'PRESENCIAL';
  }

  return 'NAO_INFORMADO';
}


// =========================================================
// NORMALIZAR NÚMERO DE CANDIDATOS
// =========================================================

function normalizarCandidatos(valor) {

  if (
    valor === undefined ||
    valor === null ||
    valor === ''
  ) {
    return null;
  }

  if (typeof valor === 'number') {
    return valor;
  }

  const texto = String(valor);

  const numeros = texto.match(/\d+/g);

  if (!numeros || numeros.length === 0) {
    return null;
  }

  return Number(
    numeros.join('')
  );
}


// =========================================================
// EXTRAÇÃO DO RECRUTADOR / JOB POSTER
// =========================================================

function extrairRecrutador(item) {

  let nome = '';
  let cargo = '';
  let linkedin = '';
  let fonte = 'NAO_INFORMADO';


  // ---------------------------------------------------------
  // 1. Campos simples/flat
  // ---------------------------------------------------------

  nome = String(firstNonEmpty([
    item.jobPosterName,
    item.recruiterName,
    item.hiringContactName,
    item.posterFullName,
    item.recruiterFullName,
    item['nome do recrutador'],
    item['nome recrutador']
  ])).trim();

  cargo = String(firstNonEmpty([
    item.jobPosterTitle,
    item.recruiterTitle,
    item.hiringContactTitle,
    item.posterHeadline,
    item.recruiterHeadline,
    item['cargo do recrutador']
  ])).trim();

  linkedin = String(firstNonEmpty([
    item.jobPosterProfileUrl,
    item.jobPosterUrl,
    item.recruiterProfileUrl,
    item.recruiterLinkedinUrl,
    item.hiringContactUrl,
    item.posterProfileUrl,
    item.posterUrl,
    item['linkedin do recrutador'],
    item['link do recrutador']
  ])).trim();

  if (nome || linkedin) {
    fonte = 'CAMPOS_DIRETOS';
  }


  // ---------------------------------------------------------
  // 2. Objeto jobPoster
  // ---------------------------------------------------------

  if (!nome) {
    nome = String(firstNonEmpty([
      getPath(item, 'jobPoster.name'),
      getPath(item, 'jobPoster.fullName'),
      getPath(item, 'jobPoster.displayName')
    ])).trim();

    if (nome) {
      fonte = 'JOB_POSTER';
    }
  }

  if (!cargo) {
    cargo = String(firstNonEmpty([
      getPath(item, 'jobPoster.title'),
      getPath(item, 'jobPoster.headline'),
      getPath(item, 'jobPoster.position')
    ])).trim();
  }

  if (!linkedin) {
    linkedin = String(firstNonEmpty([
      getPath(item, 'jobPoster.profileUrl'),
      getPath(item, 'jobPoster.linkedinUrl'),
      getPath(item, 'jobPoster.url')
    ])).trim();

    if (linkedin) {
      fonte = 'JOB_POSTER';
    }
  }


  // ---------------------------------------------------------
  // 3. Objeto recruiter
  // ---------------------------------------------------------

  if (!nome) {
    nome = String(firstNonEmpty([
      getPath(item, 'recruiter.name'),
      getPath(item, 'recruiter.fullName'),
      getPath(item, 'recruiter.displayName')
    ])).trim();

    if (nome) {
      fonte = 'RECRUITER';
    }
  }

  if (!cargo) {
    cargo = String(firstNonEmpty([
      getPath(item, 'recruiter.title'),
      getPath(item, 'recruiter.headline'),
      getPath(item, 'recruiter.position')
    ])).trim();
  }

  if (!linkedin) {
    linkedin = String(firstNonEmpty([
      getPath(item, 'recruiter.profileUrl'),
      getPath(item, 'recruiter.linkedinUrl'),
      getPath(item, 'recruiter.url')
    ])).trim();

    if (linkedin) {
      fonte = 'RECRUITER';
    }
  }


  // ---------------------------------------------------------
  // 4. Hiring Team
  // Pode vir como array
  // ---------------------------------------------------------

  const hiringTeam = firstNonEmpty([
    item.hiringTeam,
    item.hiring_team,
    item['hiring team'],
    item['equipe de contratação']
  ], []);

  if (
    Array.isArray(hiringTeam) &&
    hiringTeam.length > 0
  ) {

    const pessoa = hiringTeam[0];

    if (!nome) {
      nome = String(firstNonEmpty([
        pessoa?.name,
        pessoa?.fullName,
        pessoa?.displayName
      ])).trim();
    }

    if (!cargo) {
      cargo = String(firstNonEmpty([
        pessoa?.title,
        pessoa?.headline,
        pessoa?.position
      ])).trim();
    }

    if (!linkedin) {
      linkedin = String(firstNonEmpty([
        pessoa?.profileUrl,
        pessoa?.linkedinUrl,
        pessoa?.url
      ])).trim();
    }

    if (nome || linkedin) {
      fonte = 'HIRING_TEAM';
    }
  }


  // ---------------------------------------------------------
  // 5. Nome pode vir dividido em firstName / lastName
  // ---------------------------------------------------------

  if (!nome) {

    const firstName = String(firstNonEmpty([
      getPath(item, 'jobPoster.firstName'),
      getPath(item, 'recruiter.firstName')
    ])).trim();

    const lastName = String(firstNonEmpty([
      getPath(item, 'jobPoster.lastName'),
      getPath(item, 'recruiter.lastName')
    ])).trim();

    nome = `${firstName} ${lastName}`.trim();

    if (nome) {
      fonte = 'NOME_SEPARADO';
    }
  }


  // ---------------------------------------------------------
  // Normaliza URL
  // ---------------------------------------------------------

  linkedin = canonicalLinkedinProfileUrl(
    linkedin
  );


  return {
    nome,
    cargo,
    linkedin,
    fonte,
    encontrado: Boolean(nome || linkedin)
  };
}


// =========================================================
// ITEM RECEBIDO DO APIFY
// =========================================================

const item = $json;


// =========================================================
// CAMPOS PRINCIPAIS DA VAGA
// =========================================================

const id = String(
  get(item, [
    'id',
    'eu ia',
    'jobId',
    'job_id'
  ])
).trim();


const titulo = String(
  get(item, [
    'title',
    'título',
    'titulo',
    'jobTitle'
  ])
).trim();


const empresa = String(
  get(item, [
    'companyName',
    'nome da empresa',
    'empresa',
    'company'
  ])
).trim();


const localizacao = String(
  get(item, [
    'location',
    'localização',
    'localizacao'
  ])
).trim();


// =========================================================
// DESCRIÇÃO
// =========================================================

const descricaoHtml = String(
  get(item, [
    'descriptionHtml',
    'descricaoHtml',
    'description_html'
  ])
);


const descricaoDireta = get(item, [
  'descriptionText',
  'descricaoTexto',
  'description'
]);


const descricaoTexto = String(
  descricaoDireta ||
  stripHtml(descricaoHtml)
).trim();


// =========================================================
// LINK DA VAGA
// =========================================================

const linkOriginal = String(
  get(item, [
    'link',
    'jobUrl',
    'job_url',
    'url'
  ])
).trim();


const link = canonicalLinkedinJobUrl(
  linkOriginal,
  id
);


// =========================================================
// LINK PARA CANDIDATURA
// =========================================================

const applyUrl = String(
  get(item, [
    'applyUrl',
    'applyURL',
    'apply_url'
  ])
).trim();


// =========================================================
// DATA DA PUBLICAÇÃO
// =========================================================

const dataPublicacao = get(item, [
  'postedAt',
  'postadoEm',
  'posted_at',
  'publishedAt'
]);


// =========================================================
// CANDIDATOS
// =========================================================

const candidatosRaw = get(item, [
  'applicantsCount',
  'contagem de candidatos',
  'numeroCandidatos',
  'applicants'
], '');


const candidatos = normalizarCandidatos(
  candidatosRaw
);


// =========================================================
// MODALIDADE
// =========================================================

const modalidade = detectarModalidade(
  item,
  descricaoTexto
);


// =========================================================
// RECRUTADOR
// =========================================================

const recrutador = extrairRecrutador(
  item
);


// =========================================================
// CONTEXTO DA PESQUISA
// =========================================================

let contexto = {};

try {

  contexto =
    $('Executar Pesquisas').item.json;

} catch (e) {

  contexto = {};

}


// =========================================================
// VALIDAÇÃO
// =========================================================

const problemas = [];


if (!titulo) {
  problemas.push('SEM_CARGO');
}


if (!empresa) {
  problemas.push('SEM_EMPRESA');
}


if (!descricaoTexto) {
  problemas.push('SEM_DESCRICAO');
}


if (!id && !linkOriginal) {
  problemas.push('SEM_IDENTIFICADOR');
}


const dadosValidos =
  titulo !== '' &&
  empresa !== '' &&
  (id !== '' || linkOriginal !== '');


// =========================================================
// DEDUPE KEY
// =========================================================

const dedupeKey = id
  ? `linkedin:${id}`
  : `linkedin:${normalizeText(
      `${empresa}|${titulo}|${localizacao}`
    )}`;


// =========================================================
// OUTPUT
// =========================================================

return {
  json: {

    // -------------------------------------------------------
    // IDENTIFICAÇÃO
    // -------------------------------------------------------

    vaga_id: id,

    dedupe_key: dedupeKey,

    fonte: 'LinkedIn',


    // -------------------------------------------------------
    // DADOS DA VAGA
    // -------------------------------------------------------

    cargo: titulo,

    empresa,

    localizacao,

    modalidade_detectada:
      modalidade,


    // -------------------------------------------------------
    // PUBLICAÇÃO / CANDIDATOS
    // -------------------------------------------------------

    data_publicacao:
      dataPublicacao,

    candidatos,

    candidatos_original:
      candidatosRaw,


    // -------------------------------------------------------
    // LINKS
    // -------------------------------------------------------

    link,

    apply_url:
      applyUrl,

    company_linkedin_url:
      get(item, [
        'companyLinkedinUrl',
        'companyLinkedInUrl',
        'companyUrl'
      ]),


    // -------------------------------------------------------
    // RECRUTADOR / JOB POSTER
    // -------------------------------------------------------

    recrutador_nome:
      recrutador.nome,

    recrutador_cargo:
      recrutador.cargo,

    recrutador_linkedin:
      recrutador.linkedin,

    tem_recrutador:
      recrutador.encontrado,

    recrutador_fonte:
      recrutador.fonte,


    // -------------------------------------------------------
    // DESCRIÇÃO
    // -------------------------------------------------------

    descricao:
      descricaoTexto,


    // -------------------------------------------------------
    // ORIGEM DA BUSCA
    // -------------------------------------------------------

    busca_origem:
      contexto.busca || '',

    frente_origem:
      contexto.frente || '',

    modalidade_alvo:
      contexto.modalidade_alvo || '',

    regiao_alvo:
      contexto.regiao_alvo || '',

    prioridade_busca:
      contexto.prioridade_busca ?? null,


    // -------------------------------------------------------
    // CONTROLE / QUALIDADE
    // -------------------------------------------------------

    dados_validos:
      dadosValidos,

    problemas_normalizacao:
      problemas,

    status:
      'ENCONTRADA',

    coletada_em:
      new Date().toISOString()
  }
};

const vaga = $json;

// ========================================================
// FUNÇÕES AUXILIARES
// ========================================================

function norm(value = '') {
  return String(value)
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/\s+/g, ' ')
    .trim();
}

function escapeRegex(text = '') {
  return String(text).replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

function contem(texto, termo) {
  const t = norm(texto);
  const p = norm(termo);

  if (!p) return false;

  // Expressões com espaço podem usar includes
  if (p.includes(' ')) {
    return t.includes(p);
  }

  // Termos curtos devem respeitar limites de palavra
  return new RegExp(
    `(^|[^a-z0-9])${escapeRegex(p)}([^a-z0-9]|$)`,
    'i'
  ).test(t);
}

function algum(texto, termos = []) {
  return termos.some(termo => contem(texto, termo));
}

// ========================================================
// DADOS NORMALIZADOS
// ========================================================

const cargo = norm(vaga.cargo);
const descricao = norm(vaga.descricao);
const local = norm(vaga.localizacao);

const frente = String(vaga.frente_origem || '').trim();
const modalidade = String(
  vaga.modalidade_detectada || 'NAO_INFORMADO'
).trim();

const modalidadeAlvo = String(
  vaga.modalidade_alvo || ''
).trim();

let score = 0;
let descartar = false;

const motivos = [];
const sinais = [];

// ========================================================
// 0. QUALIDADE DOS DADOS
// ========================================================

if (vaga.dados_validos === false) {
  descartar = true;
  motivos.push('Dados básicos da vaga inválidos');
}

if (!cargo) {
  descartar = true;
  motivos.push('Cargo não informado');
}

if (!descricao) {
  motivos.push('Descrição não informada');
}

// ========================================================
// 1. SENIORIDADE
// ========================================================

const senioridadeAlta = [
  'senior',
  'sr',
  'especialista',
  'specialist',
  'lead',
  'lider',
  'principal',
  'manager',
  'gerente',
  'coordenador',
  'coordinator',
  'head',
  'director',
  'diretor',
  'architect',
  'arquiteto'
];

const senioridadeCompativel = [
  'junior',
  'jr',
  'assistente',
  'assistant',
  'entry level',
  'estagio',
  'estagiario',
  'intern',
  'trainee'
];

if (algum(cargo, senioridadeAlta)) {
  descartar = true;
  motivos.push('Senioridade do cargo acima do alvo');
}

if (algum(cargo, senioridadeCompativel)) {
  score += 20;
  sinais.push('Senioridade compatível');
}

// ========================================================
// 2. CARGOS POR FRENTE
// ========================================================

const cargosDados = [
  'analista de dados',
  'data analyst',
  'data analytics analyst',
  'analytics analyst',
  'analista de bi',
  'bi analyst',
  'business intelligence analyst',
  'business intelligence',
  'assistente de bi',
  'assistente de dados',
  'analista de indicadores',
  'analista de mis',
  'mis analyst',
  'reporting analyst',
  'report analyst',
  'analista de relatorios',
  'analista de inteligencia de dados'
];

const cargosOperacoes = [
  'analista de operacoes',
  'operations analyst',
  'analista de planejamento',
  'planning analyst',
  'assistente de planejamento',
  'analista de processos',
  'process analyst',
  'analista de performance',
  'performance analyst',
  'analista administrativo',
  'assistente administrativo'
];

const cargosFinanceiro = [
  'analista financeiro',
  'financial analyst',
  'assistente financeiro',
  'operacoes financeiras',
  'financial operations',
  'backoffice',
  'back office',
  'analista de faturamento',
  'assistente de faturamento',
  'analista administrativo'
];

const cargosEstagio = [
  'estagio',
  'estagiario',
  'intern',
  'internship'
];

const todosCargos = [
  ...cargosDados,
  ...cargosOperacoes,
  ...cargosFinanceiro,
  ...cargosEstagio
];

let cargosDaFrente = todosCargos;

if (frente === 'DADOS_BI') {
  cargosDaFrente = cargosDados;
}

if (frente === 'OPERACOES_PLANEJAMENTO') {
  cargosDaFrente = cargosOperacoes;
}

if (frente === 'FINANCEIRO_ADMINISTRATIVO') {
  cargosDaFrente = cargosFinanceiro;
}

if (frente === 'ESTAGIO_ADS') {
  cargosDaFrente = cargosEstagio;
}

const cargoRelevante = algum(
  cargo,
  frente === 'MULTIFRENTE'
    ? todosCargos
    : cargosDaFrente
);

if (cargoRelevante) {
  score += 30;
  sinais.push('Cargo relacionado à frente');
}

// ========================================================
// 3. PALAVRAS-CHAVE POR FRENTE
// ========================================================

const keywordsComuns = [
  'excel',
  'analise de dados',
  'indicadores',
  'kpi',
  'dashboard',
  'relatorios'
];

const keywordsDados = [
  'power bi',
  'sql',
  'python',
  'business intelligence',
  'analytics',
  'etl',
  'data warehouse',
  'modelagem de dados',
  'modelagem dimensional',
  'star schema',
  'banco de dados',
  'mysql',
  'visualizacao de dados'
];

const keywordsOperacoes = [
  'planejamento',
  'operacoes',
  'processos',
  'performance',
  'produtividade',
  'faturamento',
  'melhoria de processos',
  'controle operacional',
  'eficiencia operacional'
];

const keywordsFinanceiro = [
  'financeiro',
  'operacoes financeiras',
  'backoffice',
  'back office',
  'faturamento',
  'controles',
  'investimentos',
  'mercado financeiro',
  'anbima',
  'cpa',
  'c-pro'
];

const keywordsEstagio = [
  'sql',
  'power bi',
  'python',
  'banco de dados',
  'automacao',
  'api',
  'webhook',
  'n8n',
  'etl',
  'analytics'
];

let palavrasFrente = keywordsComuns;

if (frente === 'DADOS_BI') {
  palavrasFrente = [
    ...keywordsComuns,
    ...keywordsDados
  ];
}

if (frente === 'OPERACOES_PLANEJAMENTO') {
  palavrasFrente = [
    ...keywordsComuns,
    ...keywordsOperacoes
  ];
}

if (frente === 'FINANCEIRO_ADMINISTRATIVO') {
  palavrasFrente = [
    ...keywordsComuns,
    ...keywordsFinanceiro
  ];
}

if (frente === 'ESTAGIO_ADS') {
  palavrasFrente = [
    ...keywordsComuns,
    ...keywordsEstagio
  ];
}

if (frente === 'MULTIFRENTE' || !frente) {
  palavrasFrente = [
    ...keywordsComuns,
    ...keywordsDados,
    ...keywordsOperacoes,
    ...keywordsFinanceiro,
    ...keywordsEstagio
  ];
}

// Remove repetidos
palavrasFrente = [...new Set(palavrasFrente)];

const encontrados = palavrasFrente.filter(
  palavra =>
    contem(cargo, palavra) ||
    contem(descricao, palavra)
);

score += Math.min(
  encontrados.length * 4,
  28
);

if (encontrados.length > 0) {
  sinais.push(
    `${encontrados.length} palavras-chave relevantes`
  );
}

// ========================================================
// 4. MODALIDADE E LOCALIZAÇÃO
// ========================================================

// Disponibilidade REAL do candidato:
//
// REMOTO: Brasil
// HIBRIDO: São Paulo/SP
// PRESENCIAL: Baixada Santista definida abaixo

const cidadesPresenciaisAceitas = [
  'guaruja',
  'santos',
  'sao vicente',
  'praia grande',
  'cubatao',
  'bertioga'
];

const presencialCompativel =
  cidadesPresenciaisAceitas.some(
    cidade => local.includes(cidade)
  );

const saoPauloCapital =
  local.includes('sao paulo') ||
  /(^|[\s,])sp([\s,]|$)/.test(local);

// REMOTO
if (modalidade === 'REMOTO') {
  score += 15;
  sinais.push('Modalidade remota compatível');
}

// HÍBRIDO
else if (
  modalidade === 'HIBRIDO' &&
  saoPauloCapital
) {
  score += 15;
  sinais.push('Híbrido em São Paulo compatível');
}

// PRESENCIAL
else if (
  modalidade === 'PRESENCIAL' &&
  presencialCompativel
) {
  score += 15;
  sinais.push('Presencial em região compatível');
}

// Modalidade conhecida, mas incompatível
else if (modalidade === 'HIBRIDO') {
  score -= 15;
  motivos.push(
    'Híbrido fora da região de São Paulo desejada'
  );
}

else if (modalidade === 'PRESENCIAL') {
  score -= 20;
  motivos.push(
    'Presencial fora da região desejada'
  );
}

// Modalidade não informada
else if (modalidade === 'NAO_INFORMADO') {
  score += 2;
  motivos.push(
    'Modalidade não identificada automaticamente'
  );
}

// ========================================================
// 5. DIVERGÊNCIA ENTRE BUSCA E RESULTADO
// ========================================================

// Não descarta automaticamente.
//
// Exemplo:
// busca REMOTO encontrou HÍBRIDO SP.
// A vaga ainda é compatível com o candidato.

if (
  modalidadeAlvo &&
  modalidade !== 'NAO_INFORMADO' &&
  modalidade !== modalidadeAlvo
) {
  sinais.push(
    `Resultado diferente da busca (${modalidadeAlvo} → ${modalidade})`
  );
}

// ========================================================
// 6. EXPERIÊNCIA EXIGIDA
// ========================================================

function detectarAnosObrigatorios(texto = '') {

  const patterns = [
    /(?:minimo|minima|pelo menos|ao menos)\s+(?:de\s+)?(\d+)\+?\s*anos?/g,
    /(\d+)\+?\s*anos?\s+(?:de\s+)?experiencia/g,
    /minimum\s+(?:of\s+)?(\d+)\+?\s+years?/g,
    /at least\s+(\d+)\+?\s+years?/g,
    /(\d+)\+?\s+years?\s+of\s+experience/g
  ];

  let maior = 0;

  for (const regex of patterns) {
    let match;

    while ((match = regex.exec(texto)) !== null) {
      maior = Math.max(
        maior,
        Number(match[1]) || 0
      );
    }
  }

  return maior;
}

const anosObrigatorios =
  detectarAnosObrigatorios(descricao);

if (anosObrigatorios === 4) {
  score -= 8;

  motivos.push(
    'Vaga menciona 4 anos de experiência'
  );
}

if (
  anosObrigatorios >= 5 &&
  anosObrigatorios <= 6
) {
  score -= 20;

  motivos.push(
    `Vaga menciona ${anosObrigatorios} anos de experiência`
  );
}

if (anosObrigatorios >= 7) {
  descartar = true;

  motivos.push(
    `Exigência elevada de ${anosObrigatorios} anos de experiência`
  );
}

// ========================================================
// 7. ÁREAS CLARAMENTE FORA DO ALVO
// ========================================================

const cargosIrrelevantes = [
  'vendedor',
  'sales manager',
  'executivo de vendas',
  'engenheiro civil',
  'enfermeiro',
  'medico',
  'advogado',
  'designer grafico',
  'social media',
  'marketing manager',
  'recrutador',
  'recruiter',
  'recursos humanos',
  'human resources'
];

if (algum(cargo, cargosIrrelevantes)) {
  descartar = true;

  motivos.push(
    'Área claramente fora das frentes profissionais'
  );
}

// ========================================================
// 8. ESTÁGIOS FORA DO FOCO
// ========================================================

if (frente === 'ESTAGIO_ADS') {

  const estagiosForaDoFoco = [
    'help desk',
    'suporte tecnico',
    'service desk',
    'infraestrutura',
    'redes',
    'manutencao de computadores',
    'field service'
  ];

  if (
    algum(cargo, estagiosForaDoFoco) ||
    estagiosForaDoFoco.filter(
      x => contem(descricao, x)
    ).length >= 2
  ) {
    descartar = true;

    motivos.push(
      'Estágio predominantemente fora do foco de Dados/Automação/Sistemas'
    );
  }
}

// ========================================================
// 9. PROTEÇÃO CONTRA CARGO SEM RELAÇÃO
// ========================================================

// Se o título não bate com nenhuma frente,
// exige pelo menos alguns sinais técnicos relevantes.
//
// Evita vagas aleatórias passarem apenas porque
// a descrição contém Excel ou SQL.

if (
  !cargoRelevante &&
  encontrados.length < 3
) {
  score -= 20;

  motivos.push(
    'Cargo pouco relacionado e poucos sinais relevantes'
  );
}

// ========================================================
// 10. NORMALIZA SCORE
// ========================================================

score = Math.max(
  0,
  Math.min(100, score)
);

// ========================================================
// 11. REGRA FINAL
// ========================================================

let preFiltro;

if (descartar) {

  preFiltro = 'DESCARTAR';

} else if (score >= 40) {

  preFiltro = 'ANALISAR';

} else {

  preFiltro = 'DESCARTAR';

  motivos.push(
    'Baixa aderência no pré-filtro'
  );
}

// ========================================================
// OUTPUT
// ========================================================

return {
  json: {
    ...vaga,

    pre_score: score,

    pre_filtro: preFiltro,

    sinais_pre_filtro: sinais,

    motivos_pre_filtro: motivos,

    palavras_relevantes_encontradas:
      encontrados,

    quantidade_palavras_relevantes:
      encontrados.length,

    cargo_relevante:
      cargoRelevante,

    anos_experiencia_identificados:
      anosObrigatorios,

    presencial_compativel:
      presencialCompativel,

    sao_paulo_compativel:
      saoPauloCapital
  }
};

const item = $json;

// ========================================================
// 1. VALIDAR OUTPUT DA IA
// ========================================================

if (
  !item.output ||
  typeof item.output !== 'object' ||
  Array.isArray(item.output)
) {
  throw new Error(
    'Calcular Score Final não recebeu o output estruturado da IA. Verifique o Merge Classificação.'
  );
}

const ai = item.output;

const { output, ...dadosOriginais } = item;

// ========================================================
// 2. CAMPOS OBRIGATÓRIOS
// ========================================================

const camposObrigatorios = [
  'score_tecnico',
  'score_experiencia',
  'score_senioridade',
  'score_modalidade_localizacao',
  'score_formacao',
  'score_diferenciais',
  'eliminatorio',
  'motivo_eliminatorio',
  'frente_sugerida',
  'senioridade_detectada',
  'resumo_aderencia'
];

const camposAusentes = camposObrigatorios.filter(
  campo =>
    ai[campo] === undefined ||
    ai[campo] === null
);

if (camposAusentes.length > 0) {
  throw new Error(
    `Classificação da IA incompleta. Campos ausentes: ${camposAusentes.join(', ')}`
  );
}

// ========================================================
// 3. AUXILIAR
// ========================================================

function clampInt(value, min, max) {
  const numero = Number(value);

  if (!Number.isFinite(numero)) {
    throw new Error(
      `Score inválido recebido da IA: ${value}`
    );
  }

  return Math.max(
    min,
    Math.min(max, Math.round(numero))
  );
}

// ========================================================
// 4. SCORES
// ========================================================

const componentes = {
  tecnico:
    clampInt(ai.score_tecnico, 0, 35),

  experiencia:
    clampInt(ai.score_experiencia, 0, 25),

  senioridade:
    clampInt(ai.score_senioridade, 0, 15),

  modalidade_localizacao:
    clampInt(
      ai.score_modalidade_localizacao,
      0,
      10
    ),

  formacao:
    clampInt(ai.score_formacao, 0, 5),

  diferenciais:
    clampInt(ai.score_diferenciais, 0, 10)
};

const scoreBruto =
  componentes.tecnico +
  componentes.experiencia +
  componentes.senioridade +
  componentes.modalidade_localizacao +
  componentes.formacao +
  componentes.diferenciais;

// ========================================================
// 5. ELIMINATÓRIO
// ========================================================

const eliminatorio =
  ai.eliminatorio === true;

const scoreFinal =
  eliminatorio
    ? Math.min(scoreBruto, 49)
    : scoreBruto;

// ========================================================
// 6. CLASSIFICAÇÃO
// ========================================================

let classificacao;
let acao;

if (eliminatorio) {
  classificacao = 'DESCARTAR';
  acao = 'ARQUIVAR';

} else if (scoreFinal >= 80) {
  classificacao = 'ALTA';
  acao = 'PREPARAR_CANDIDATURA';

} else if (scoreFinal >= 65) {
  classificacao = 'MEDIA';
  acao = 'REVISAR';

} else if (scoreFinal >= 50) {
  classificacao = 'BAIXA';
  acao = 'REGISTRAR';

} else {
  classificacao = 'DESCARTAR';
  acao = 'ARQUIVAR';
}

// ========================================================
// 7. VALIDAR FRENTE
// ========================================================

const frentesPermitidas = [
  'DADOS_BI',
  'OPERACOES_PLANEJAMENTO',
  'FINANCEIRO_ADMINISTRATIVO',
  'ESTAGIO_ADS',
  'OUTRA'
];

const frenteSugerida =
  frentesPermitidas.includes(
    ai.frente_sugerida
  )
    ? ai.frente_sugerida
    : 'OUTRA';

// ========================================================
// 8. VALIDAR SENIORIDADE
// ========================================================

const senioridadesPermitidas = [
  'ESTAGIO',
  'ASSISTENTE',
  'JUNIOR',
  'PLENO',
  'SENIOR',
  'ESPECIALISTA_LIDERANCA',
  'NAO_INFORMADA'
];

const senioridadeDetectada =
  senioridadesPermitidas.includes(
    ai.senioridade_detectada
  )
    ? ai.senioridade_detectada
    : 'NAO_INFORMADA';

// ========================================================
// 9. OUTPUT FINAL
// ========================================================

return {
  json: {
    ...dadosOriginais,

    score_tecnico:
      componentes.tecnico,

    score_experiencia:
      componentes.experiencia,

    score_senioridade:
      componentes.senioridade,

    score_modalidade_localizacao:
      componentes.modalidade_localizacao,

    score_formacao:
      componentes.formacao,

    score_diferenciais:
      componentes.diferenciais,

    score_componentes:
      componentes,

    score_bruto:
      scoreBruto,

    score_final:
      scoreFinal,

    classificacao,
    acao,

    eliminatorio,

    motivo_eliminatorio:
      eliminatorio
        ? String(ai.motivo_eliminatorio || '').trim()
        : '',

    frente_sugerida:
      frenteSugerida,

    senioridade_detectada:
      senioridadeDetectada,

    resumo_aderencia:
      String(ai.resumo_aderencia || '').trim(),

    classificacao_valida:
      true
  }
};

const item = $json;

// ========================================================
// 1. RESPOSTA DA IA
// ========================================================

const analise =
  item.output &&
  typeof item.output === 'object' &&
  !Array.isArray(item.output)
    ? item.output
    : {};

// ========================================================
// 2. FUNÇÕES AUXILIARES
// ========================================================

function limparTexto(valor) {
  return String(valor || '')
    .replace(/\s+/g, ' ')
    .trim();
}

function limparLista(valor, maxItens) {
  if (!Array.isArray(valor)) {
    return [];
  }

  return valor
    .map(limparTexto)
    .filter(Boolean)
    .slice(0, maxItens);
}

function formatarLista(lista) {
  return lista.length
    ? lista.join(' | ')
    : 'Nenhum identificado';
}

// ========================================================
// 3. NORMALIZAR ANÁLISE
// ========================================================

const pontosFortes =
  limparLista(
    analise.pontos_fortes,
    4
  );

const requisitosParciais =
  limparLista(
    analise.requisitos_parciais,
    3
  );

const requisitosAusentes =
  limparLista(
    analise.requisitos_ausentes,
    3
  );

const palavrasChaveAts =
  limparLista(
    analise.palavras_chave_ats,
    10
  );

const estrategiaCurriculo =
  limparTexto(
    analise.estrategia_curriculo
  );

const mensagemRecrutador =
  limparTexto(
    analise.mensagem_recrutador
  );

// ========================================================
// 4. DADOS DA VAGA
// ========================================================

const cargo =
  limparTexto(item.cargo) ||
  'Não informado';

const empresa =
  limparTexto(item.empresa) ||
  'Não informada';

const localizacao =
  limparTexto(item.localizacao) ||
  'Não informada';

const modalidade =
  limparTexto(item.modalidade_detectada) ||
  'Não informada';

// ========================================================
// 5. GERAR PROMPT COMPACTO DO CURRÍCULO
// ========================================================

const promptCurriculo = `
Adapte meu Currículo Mestre para esta vaga.

VAGA
Cargo: ${cargo}
Empresa: ${empresa}
Localização: ${localizacao}
Modalidade: ${modalidade}

PONTOS FORTES
${formatarLista(pontosFortes)}

REQUISITOS PARCIAIS
${formatarLista(requisitosParciais)}

REQUISITOS AUSENTES
${formatarLista(requisitosAusentes)}

PALAVRAS-CHAVE
${formatarLista(palavrasChaveAts)}

ESTRATÉGIA
${estrategiaCurriculo || 'Não informada'}

INSTRUÇÕES
Vou fornecer meu Currículo Mestre junto com este prompt. Adapte-o especificamente para esta oportunidade e use o currículo mestre como fonte factual principal.

Priorize no título, resumo, experiências, projetos e competências o que tiver relação real com a vaga. Nas experiências, preserve empresa, cargo oficial e período, mas reorganize os bullets para destacar primeiro as atividades mais relevantes. Não crie resultados ou números.

Projetos podem demonstrar conhecimento técnico, mas nunca devem ser apresentados como experiência profissional. Destaque somente projetos relevantes.

Priorize competências e palavras-chave compatíveis com o perfil. Não afirme requisitos listados como ausentes.

Não invente experiência, empresa, cargo, datas, tecnologias, certificações, resultados, números, idiomas ou nível de conhecimento. Não transforme projeto ou estudo em experiência profissional. Não atribua senioridade, especialização, domínio avançado ou experiência profissional sem evidência.

Preserve formação e certificações. Produza currículo profissional, objetivo, natural e compatível com ATS. Sem foto, gráficos, barras de habilidade ou tabelas. Priorize uma página A4 quando possível.

Ordem sugerida: NOME E CONTATO; TÍTULO PROFISSIONAL; RESUMO PROFISSIONAL; EXPERIÊNCIA PROFISSIONAL; PROJETOS RELEVANTES; COMPETÊNCIAS; FORMAÇÃO; CERTIFICAÇÕES; IDIOMAS E INFORMAÇÕES ADICIONAIS.

Não explique as alterações. Retorne somente o conteúdo final do currículo adaptado.
`
  .trim()
  .replace(/\n{3,}/g, '\n\n');

// ========================================================
// 6. REMOVER OUTPUT ANINHADO
// ========================================================

const {
  output,
  ...dadosOriginais
} = item;

// ========================================================
// 7. CONTROLE DE TAMANHO
// ========================================================

const tamanhoPrompt =
  promptCurriculo.length;

// ========================================================
// 8. OUTPUT FINAL
// ========================================================

return {
  json: {
    ...dadosOriginais,

    pontos_fortes:
      pontosFortes,

    requisitos_parciais:
      requisitosParciais,

    requisitos_ausentes:
      requisitosAusentes,

    palavras_chave_ats:
      palavrasChaveAts,

    estrategia_curriculo:
      estrategiaCurriculo,

    mensagem_recrutador:
      mensagemRecrutador,

    prompt_curriculo:
      promptCurriculo,

    prompt_curriculo_caracteres:
      tamanhoPrompt,

    prompt_cabe_em_uma_mensagem_telegram:
      tamanhoPrompt <= 3800
  }
};

